        _testIsValidSignature("A(B b)B(bytes32 stuff)", "B", true, true);
        _testIsValidSignature("A(B b)B(bytes32 stuff)", "", true, false);
        _testIsValidSignature("A(B b)B(bytes32 stuff)", "c", true, false);

