        if (y == 0) y = 1;
        int256 z = FixedPointMathLib.sDivWad(x, y);
        assertEq(z, (x * 1e18) / y);
        assertEq(FixedPointMathLib.rawSDivWad(x, y), z);
        assertEq(FixedPointMathLib.sDivWad(-x, y), -z);
        assertLe(
            FixedPointMathLib.abs(z) * FixedPointMathLib.abs(y), FixedPointMathLib.abs(x) * 1e18
        );
    }

