        bytes memory encoded = abi.encodePacked(x, y);
        (bytes32 xDecoded, bytes32 yDecoded) = P256.tryDecodePoint(encoded);
        assertEq(xDecoded, x);
        assertEq(yDecoded, y);
        this.tryDecodePointCalldata(encoded, x, y);
